-- ============================================================================
-- FLEXCUBE-NAMED GL / GENERAL LEDGER SEED DATA (17-table reference DDL)
-- ============================================================================
-- Purpose: populate the tables defined in flexcube_gl_documented_reference_ddl.sql.
-- Maker/checker requested: MAKER_ID = SAMNANG; CHECKER_ID = FLEXCUBE where those
-- columns exist. Ledger entries use USER_ID = SAMNANG and AUTH_ID = FLEXCUBE.
--
-- BUSINESS DATA NOTICE:
-- All accounts, balances, references, and entries below are realistic SYNTHETIC
-- training records for the fictional ABC Bank lab schema, not actual customer or
-- bank ledger data. Date aligns with the previous Common Services lab seed date
-- 2026-10-13; prior-day historical examples use 2026-10-12. FX uses 4,012 KHR/USD
-- as a lab rate carried from an earlier historical Common Services snapshot;
-- it is not represented as a live FX rate.
--
-- DEPENDENCIES: run the matching Common Services DDL + seed first. Required rows:
-- STTM_BRANCH branch codes 001/002/003 and CYTM_CCY_DEFN currencies KHR/USD.
-- This seed matches the documented-reference GL DDL with these 17 tables; it does
-- not create GLTB_GL_BAL (that table is in a different, smaller GL DDL variant).
-- Run only in an isolated training schema. Never manually seed live FLEXCUBE
-- accounting tables in production. Script is rerunnable by stable-key MERGE.
-- ============================================================================
SET DEFINE OFF
SET SERVEROUTPUT ON
PROMPT Checking Common Services prerequisites...
DECLARE
    v_count PLS_INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM USER_TABLES
     WHERE TABLE_NAME IN ('STTM_BRANCH','CYTM_CCY_DEFN');
    IF v_count <> 2 THEN
        RAISE_APPLICATION_ERROR(-20001, 'Required tables STTM_BRANCH and CYTM_CCY_DEFN must exist in this schema. Run Common Services DDL first.');
    END IF;
    SELECT COUNT(*) INTO v_count FROM STTM_BRANCH WHERE BRANCH_CODE IN ('001','002','003');
    IF v_count <> 3 THEN
        RAISE_APPLICATION_ERROR(-20002, 'Seed branches 001, 002, and 003 must exist in STTM_BRANCH. Run Common Services seed data first.');
    END IF;
    SELECT COUNT(*) INTO v_count FROM CYTM_CCY_DEFN WHERE CCY_CODE IN ('KHR','USD');
    IF v_count <> 2 THEN
        RAISE_APPLICATION_ERROR(-20003, 'Currencies KHR and USD must exist in CYTM_CCY_DEFN. Run Common Services seed data first.');
    END IF;
END;
/
PROMPT Prerequisites found. Starting GL seed data...

PROMPT 1. GL hierarchy level 1: root accounts (maker SAMNANG / checker FLEXCUBE).
MERGE INTO GLTM_GLMASTER t
USING (
    SELECT '100000000' AS GL_CODE, 'ASSETS' AS GL_DESC, NULL AS PARENT_GL, 'N' AS CCY_RES, NULL AS RES_CCY, 'N' AS LEAF, 'N' AS CUSTOMER, 'N' AS REVAL, 'N' AS BLOCK, 'N' AS POSTING_RES, 'N' AS RECON, 'O' AS RECORD_STAT, 'Y' AS ONCE_AUTH, 'A' AS AUTH_STAT, 1 AS MOD_NO, 'SAMNANG' AS MAKER_ID, DATE '2026-10-13' AS MAKER_DT_STAMP, 'FLEXCUBE' AS CHECKER_ID, DATE '2026-10-13' AS CHECKER_DT_STAMP, NULL AS ULTI_PARENT, 'N' AS FLG_POSITION_AC, 'N' AS CCY_POS_GL, 'N' AS HO_RES, 'Y' AS FIRST_AUTH FROM DUAL
