    UNION ALL
    SELECT '600000000' AS GL_CODE, 'CONTINGENT AND MEMORANDUM' AS GL_DESC, NULL AS PARENT_GL, 'N' AS CCY_RES, NULL AS RES_CCY, 'N' AS LEAF, 'N' AS CUSTOMER, 'N' AS REVAL, 'N' AS BLOCK, 'N' AS POSTING_RES, 'N' AS RECON, 'O' AS RECORD_STAT, 'Y' AS ONCE_AUTH, 'A' AS AUTH_STAT, 1 AS MOD_NO, 'SAMNANG' AS MAKER_ID, DATE '2026-10-13' AS MAKER_DT_STAMP, 'FLEXCUBE' AS CHECKER_ID, DATE '2026-10-13' AS CHECKER_DT_STAMP, NULL AS ULTI_PARENT, 'N' AS FLG_POSITION_AC, 'N' AS CCY_POS_GL, 'N' AS HO_RES, 'Y' AS FIRST_AUTH FROM DUAL
) s
ON (t.GL_CODE = s.GL_CODE)
WHEN MATCHED THEN
    UPDATE SET t.GL_DESC = s.GL_DESC,
               t.PARENT_GL = s.PARENT_GL,
               t.CCY_RES = s.CCY_RES,
               t.RES_CCY = s.RES_CCY,
