    VALUES (s.GL_CODE, s.GL_DESC, s.PARENT_GL, s.CCY_RES, s.RES_CCY, s.LEAF, s.CUSTOMER, s.REVAL, s.BLOCK, s.POSTING_RES, s.RECON, s.RECORD_STAT, s.ONCE_AUTH, s.AUTH_STAT, s.MOD_NO, s.MAKER_ID, s.MAKER_DT_STAMP, s.CHECKER_ID, s.CHECKER_DT_STAMP, s.ULTI_PARENT, s.FLG_POSITION_AC, s.CCY_POS_GL, s.HO_RES, s.FIRST_AUTH);

