PROMPT 4. GL control/report selectors by branch.
MERGE INTO GLTB_CTL t
USING (
    SELECT '001' AS BRANCH_CODE, 'TRIAL_BALANCE' AS REPORT, '001' AS TID FROM DUAL
    UNION ALL
    SELECT '001' AS BRANCH_CODE, 'GL_SUMMARY' AS REPORT, '001' AS TID FROM DUAL
    UNION ALL
    SELECT '001' AS BRANCH_CODE, 'RECON_REPORT' AS REPORT, '001' AS TID FROM DUAL
    UNION ALL
    SELECT '002' AS BRANCH_CODE, 'TRIAL_BALANCE' AS REPORT, '002' AS TID FROM DUAL
    UNION ALL
    SELECT '002' AS BRANCH_CODE, 'GL_SUMMARY' AS REPORT, '002' AS TID FROM DUAL
    UNION ALL
    SELECT '002' AS BRANCH_CODE, 'RECON_REPORT' AS REPORT, '002' AS TID FROM DUAL
    UNION ALL
    SELECT '003' AS BRANCH_CODE, 'TRIAL_BALANCE' AS REPORT, '003' AS TID FROM DUAL
    UNION ALL
    SELECT '003' AS BRANCH_CODE, 'GL_SUMMARY' AS REPORT, '003' AS TID FROM DUAL
    UNION ALL
    SELECT '003' AS BRANCH_CODE, 'RECON_REPORT' AS REPORT, '003' AS TID FROM DUAL
) s
ON (t.BRANCH_CODE = s.BRANCH_CODE AND t.REPORT = s.REPORT AND t.TID = s.TID)
WHEN NOT MATCHED THEN
    INSERT (BRANCH_CODE, REPORT, TID)
    VALUES (s.BRANCH_CODE, s.REPORT, s.TID);

