    SELECT 'ABC_BASIC' AS FORMATNAME, 'FCY_AMOUNT' AS TAGNAME, '06' AS TAGPOS, 'FCY AMOUNT' AS TAGHEADING, 1 AS LINENUM, 6 AS COLNUM, 'N' AS BOLDFONT, 'R' AS JUSTIFY, 'ENG' AS LANG FROM DUAL
    UNION ALL
    SELECT 'ABC_BASIC' AS FORMATNAME, 'LCY_AMOUNT' AS TAGNAME, '07' AS TAGPOS, 'LOCAL AMOUNT' AS TAGHEADING, 1 AS LINENUM, 7 AS COLNUM, 'N' AS BOLDFONT, 'R' AS JUSTIFY, 'ENG' AS LANG FROM DUAL
    UNION ALL
    SELECT 'ABC_BASIC' AS FORMATNAME, 'AC_NO' AS TAGNAME, '08' AS TAGPOS, 'ACCOUNT / GL' AS TAGHEADING, 1 AS LINENUM, 8 AS COLNUM, 'N' AS BOLDFONT, 'L' AS JUSTIFY, 'ENG' AS LANG FROM DUAL
) s
ON (t.FORMATNAME = s.FORMATNAME AND t.LANG = s.LANG AND t.LINENUM = s.LINENUM AND t.COLNUM = s.COLNUM)
WHEN MATCHED THEN
    UPDATE SET t.TAGNAME = s.TAGNAME,
               t.TAGPOS = s.TAGPOS,
               t.TAGHEADING = s.TAGHEADING,
               t.BOLDFONT = s.BOLDFONT,
               t.JUSTIFY = s.JUSTIFY
WHEN NOT MATCHED THEN
    INSERT (FORMATNAME, TAGNAME, TAGPOS, TAGHEADING, LINENUM, COLNUM, BOLDFONT, JUSTIFY, LANG)
    VALUES (s.FORMATNAME, s.TAGNAME, s.TAGPOS, s.TAGHEADING, s.LINENUM, s.COLNUM, s.BOLDFONT, s.JUSTIFY, s.LANG);

PROMPT Optional GLTB_GL_BAL seed (runs only if that table exists in this schema)...
DECLARE
    v_exists PLS_INTEGER;
    v_count PLS_INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_exists FROM USER_TABLES WHERE TABLE_NAME = 'GLTB_GL_BAL';
    IF v_exists = 1 THEN
        EXECUTE IMMEDIATE q'~
            MERGE INTO GLTB_GL_BAL t
            USING (
                SELECT '001' AS BRANCH_CODE, '111000001' AS GL_CODE, 'KHR' AS CCY_CODE, 'FY2026' AS FIN_YEAR, 'OCT' AS PERIOD_CODE, 2500000 AS DR_MOV_LCY, 1200000 AS CR_MOV_LCY FROM DUAL
                UNION ALL SELECT '001','112000001','KHR','FY2026','OCT',0,40120000 FROM DUAL
                UNION ALL SELECT '001','112000002','USD','FY2026','OCT',40120000,0 FROM DUAL
                UNION ALL SELECT '001','121000001','KHR','FY2026','OCT',20000000,0 FROM DUAL
                UNION ALL SELECT '001','211000001','KHR','FY2026','OCT',375000,22500000 FROM DUAL
                UNION ALL SELECT '001','411000001','KHR','FY2026','OCT',0,350000 FROM DUAL
                UNION ALL SELECT '001','411000002','KHR','FY2026','OCT',0,25000 FROM DUAL
                UNION ALL SELECT '001','521000001','KHR','FY2026','OCT',1200000,0 FROM DUAL
            ) s
            ON (t.BRANCH_CODE = s.BRANCH_CODE AND t.GL_CODE = s.GL_CODE AND t.CCY_CODE = s.CCY_CODE AND t.FIN_YEAR = s.FIN_YEAR AND t.PERIOD_CODE = s.PERIOD_CODE)
            WHEN MATCHED THEN UPDATE SET t.DR_MOV_LCY = s.DR_MOV_LCY, t.CR_MOV_LCY = s.CR_MOV_LCY
            WHEN NOT MATCHED THEN INSERT (BRANCH_CODE, GL_CODE, CCY_CODE, FIN_YEAR, PERIOD_CODE, DR_MOV_LCY, CR_MOV_LCY)
                 VALUES (s.BRANCH_CODE, s.GL_CODE, s.CCY_CODE, s.FIN_YEAR, s.PERIOD_CODE, s.DR_MOV_LCY, s.CR_MOV_LCY)
        ~';
        EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM GLTB_GL_BAL' INTO v_count;
        DBMS_OUTPUT.PUT_LINE('Optional GLTB_GL_BAL available; current row count = ' || v_count);
    ELSE
        DBMS_OUTPUT.PUT_LINE('GLTB_GL_BAL not found in this DDL variant; optional seed skipped.');
    END IF;
END;
/

PROMPT Committing GL lab seed records...
COMMIT;

PROMPT === Current-day ledger balance check (D debit / C credit) ===
SELECT TRN_REF_NO,
       SUM(CASE WHEN DRCR_IND = 'D' THEN NVL(LCY_AMOUNT,0) ELSE 0 END) AS TOTAL_DEBIT_LCY,
       SUM(CASE WHEN DRCR_IND = 'C' THEN NVL(LCY_AMOUNT,0) ELSE 0 END) AS TOTAL_CREDIT_LCY,
       SUM(CASE WHEN DRCR_IND = 'D' THEN NVL(LCY_AMOUNT,0) ELSE -NVL(LCY_AMOUNT,0) END) AS NET_LCY
FROM ACTB_DAILY_LOG
WHERE TRN_REF_NO IN ('DEP261013000001','LD261013000001','INT261013000001',
                    'FEE261013000001','GL261013000001','FX261013000001')
GROUP BY TRN_REF_NO
ORDER BY TRN_REF_NO;

